from collections import defaultdict

def chains(n):
 if not n:return [[0]]
 cs=[]
 for C in chains(n-1):
  cs.append(C+[C[-1]|(1<<(n-1))])
  if len(C)>1:cs.append([x|(1<<(n-1)) for x in C[:-1]])
 return sorted(cs,key=len)
def ideals(n):
